code_sketch:
type Tok = { kind: 'num'; text: string; pos: number }
  | { kind: 'plus' } | { kind: 'minus' }
  | { kind: 'lparen' } | { kind: 'rparen' };

function expr(p: { toks: Tok[]; i: number }): Node {
  let left = term(p);
  while (p.toks[p.i].kind === 'plus' || p.toks[p.i].kind === 'minus') {  // loop, not left recursion
    const op = p.toks[p.i++].kind;
    left = { type: 'binary', op, left, right: term(p) };
  }
  return left;
}

